class Solution {
public:
    int shortestWay(string source, string target) {
        int used = 0;
        int pos = 0;
        while (pos < static_cast<int>(target.size())) {
            int before = pos;
            for (char c : source) {
                if (pos < static_cast<int>(target.size()) && c == target[pos]) {
                    ++pos;
                }
            }
            if (pos == before) {
                return -1;
            }
            ++used;
        }
        return used;
    }
};
